#!/usr/bin/env python3
import base64
import datetime as dt
import os
import re
import shutil
import subprocess
from pathlib import Path

FILES = {"functions/api/waitlist.js": "", "functions/api/admin/_auth.js": "", "functions/api/admin/auth.js": "", "functions/api/admin/logout.js": "", "functions/api/admin/waitlist.js": "", "functions/api/admin/notifications.js": "", "admin.html": "", "admin.css": "", "admin.js": "", "app.js": "", "styles.css": "", "schema.sql": ""}
ROOT = Path.cwd()

def run(*args):
    return subprocess.run(args, cwd=ROOT, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

git_root = run("git", "rev-parse", "--show-toplevel")
if git_root.returncode == 0:
    ROOT = Path(git_root.stdout.strip())
    os.chdir(ROOT)

stamp = dt.datetime.now().strftime("%Y%m%d-%H%M%S")
backup = ROOT / ".dots-backup" / stamp
backup.mkdir(parents=True, exist_ok=True)

if run("git", "rev-parse", "--is-inside-work-tree").returncode == 0:
    branch = f"dots-world-class-{stamp}"
    created = run("git", "switch", "-c", branch)
    print(f"Git branch: {branch}" if created.returncode == 0 else "Git branch creation skipped; backup still created.")

print(f"Repository: {ROOT}")
print(f"Backup:     {backup}")

for rel in FILES:
    src = ROOT / rel
    if src.exists():
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)

for rel, encoded in FILES.items():
    dst = ROOT / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_bytes(base64.b64decode(encoded))

index = ROOT / "index.html"
s = index.read_text(encoding="utf-8")

if '<link rel="stylesheet" href="/styles.css">' not in s:
    font_link = '<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">'
    if font_link in s:
        s = s.replace(font_link, font_link + '\n    <link rel="stylesheet" href="/styles.css">', 1)
    else:
        s = s.replace('</head>', '    <link rel="stylesheet" href="/styles.css">\n</head>', 1)

s = re.sub(r'<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3\.12\.2/gsap\.min\.js"(?: defer)?></script>', '<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js" defer></script>', s)
s = re.sub(r'<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3\.12\.2/ScrollTrigger\.min\.js"(?: defer)?></script>', '<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js" defer></script>', s)
s = re.sub(r'<script src="https://unpkg\.com/@studio-freight/lenis@1\.0\.33/dist/lenis\.min\.js"(?: defer)?></script>', '<script src="https://unpkg.com/@studio-freight/lenis@1.0.33/dist/lenis.min.js" defer></script>', s)
if '<script src="/app.js" defer></script>' not in s:
    s = s.replace('</head>', '    <script src="/app.js" defer></script>\n</head>', 1)

s = re.sub(r'\s*<!-- INLINED JAVASCRIPT FOR ZERO-FAILURE EXECUTION -->\s*<script>.*?</script>\s*(?=</body>)', '\n', s, flags=re.S)
s = s.replace(' onsubmit="event.preventDefault(); window.submitWaitlist(); return false;"', '')

s = s.replace(
    '<input type="text" id="waitlistName" required placeholder="Name"',
    '<div aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden"><label>Website<input id="waitlistWebsite" name="website" tabindex="-1" autocomplete="off"></label></div>\n                <input type="text" id="waitlistName" name="name" autocomplete="name" required placeholder="Name"',
    1
)
s = s.replace(
    '<input type="email" id="waitlistEmail" required placeholder="Email Address"',
    '<input type="email" id="waitlistEmail" name="email" autocomplete="email" inputmode="email" required placeholder="Email Address"',
    1
)
old_msg = '<div id="waitlistMsg" class="mt-8 text-lg font-medium hidden"></div>'
new_msg = """<div id="waitlistSuccess" aria-live="polite">
                <div class="text-5xl mb-5">✓</div>
                <h4 class="text-3xl md:text-5xl font-bold tracking-tight text-[#111]">You're on the list.</h4>
                <p class="mt-4 text-gray-500 text-base md:text-lg">Check your inbox for your confirmation from dots.</p>
            </div>
            <div id="waitlistMsg" class="hidden" aria-live="polite"></div>"""
if old_msg in s:
    s = s.replace(old_msg, new_msg, 1)
index.write_text(s, encoding="utf-8")

print("\nInstalled the dots. production/world-class patch.")
print("Next steps:")
print("  1. git diff --stat")
print("  2. Review DEPLOY.md")
print("  3. Configure ADMIN_PASSWORD, ADMIN_SESSION_SECRET, RESEND_API_KEY")
print("  4. Verify the D1 schema on the REMOTE database")
print("  5. Deploy")
